static int32_t handle_hungup_result(int32_t result)
{
    __inf("[%s],dial hungup result = %d",__func__,result);

    if (0 != result) {
        /* wait remote accept call,do nothing */
        }
    else {
        __inf("[%s],hungup fail",__func__);
        }

    return 0;
}




void dial_key_event(uint32_t key,lv_obj_t * ui_Screen)
{
    ui_screen_dial_obj_t * p_screen_param;

    p_screen_param      = (ui_screen_dial_obj_t *) lv_obj_get_user_data(ui_Screen);

    switch (key)
    {
        case LV_KEY_UP:
            {
                uint32_t        per,vol;

                vol                 = call_fp_flow_get_call_volume();

                vol++;

                if (vol > CALL_MVOL_LEVEL_MAX)
                    vol = CALL_MVOL_LEVEL_MAX;

                call_fp_flow_set_call_volume(vol);
                per                 = 100 * vol / CALL_MVOL_LEVEL_MAX;

                if (per > 100)
                    per = 100;

                lv_slider_set_value(p_screen_param->obj_slider_vol,per,LV_ANIM_OFF);
                p_screen_param->count_hidden_slider_vol = 4;
                lv_obj_clear_flag(p_screen_param->obj_slider_vol,LV_OBJ_FLAG_HIDDEN);
                }
            break;

        case LV_KEY_DOWN:
            {
                uint32_t        per,vol;

                vol                 = call_fp_flow_get_call_volume();

                if (vol > CALL_MVOL_LEVEL_MIN)
                    vol--;

                call_fp_flow_set_call_volume(vol);
                per                 = 100 * vol / CALL_MVOL_LEVEL_MAX;

                if (per > 100)
                    per = 100;

                lv_slider_set_value(p_screen_param->obj_slider_vol,per,LV_ANIM_OFF);
                p_screen_param->count_hidden_slider_vol = 4;
                lv_obj_clear_flag(p_screen_param->obj_slider_vol,LV_OBJ_FLAG_HIDDEN);
                }
            break;

        case APP_KEY_VALUE_TOP_LEFT:
            {
                }
            break;

        case LV_KEY_END:
        case APP_KEY_VALUE_TOP_RIGHT:
            {

                alv_am_win_enter(NULL,"hangup",&p_screen_param->enter_param);
                call_fp_flow_hungup(handle_hungup_result);
                }
            break;

        case LV_KEY_ENTER:
            {

                }
            break;
        }
}



void dial_timer_stop(lv_obj_t * ui_Screen)
{
    ui_screen_dial_obj_t * p_screen_param;

    p_screen_param      = (ui_screen_dial_obj_t *) lv_obj_get_user_data(ui_Screen);

    if (p_screen_param->handle_timer != NULL) {
        lv_timer_del(p_screen_param->handle_timer);
        p_screen_param->handle_timer = NULL;
        }

}


static void dial_timer_event_cb(struct _lv_timer_t *timer)
{
    ui_screen_dial_obj_t * p_screen_param;

    p_screen_param      = timer->user_data;

    if (p_screen_param->count_hidden_slider_vol > 0) {
        p_screen_param->count_hidden_slider_vol--;

        if (p_screen_param->count_hidden_slider_vol == 0) {
            lv_obj_add_flag(p_screen_param->obj_slider_vol,LV_OBJ_FLAG_HIDDEN);
            }
        }
}


void dial_timer_start(lv_obj_t * ui_Screen)
{
    ui_screen_dial_obj_t * p_screen_param;

    p_screen_param      = (ui_screen_dial_obj_t *) lv_obj_get_user_data(ui_Screen);


    if (p_screen_param->handle_timer == NULL) {
        p_screen_param->handle_timer = lv_timer_create(dial_timer_event_cb,500,p_screen_param);
        }

}





